script.source:
if (ctx.damageType !== "Wounds" || ctx.damageValue <= 0) return false;
if (
  !(await H.ask.confirm({
    title: "Duck and Cover",
    bodyHtml:
      "<div>A Hunter in your area may <strong>Take Cover</strong> as an immediate action (Duck and Cover).</div>",
    yesLabel: "Grant Take Cover",
    noLabel: "Skip",
  }))
)
  return false;
await H.effects.apply([{ type: "grantManoeuvre", scope: "zoneMate", manoeuvre: "take-cover" }], ctx);
return !ctx._cancelled;
